--
-- Name: trades Users can view trades shared in community messages; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Users can view trades shared in community messages" ON "public"."trades" FOR SELECT USING (("id" IN ( SELECT "community_messages"."trade_id"
   FROM "public"."community_messages"
  WHERE ("community_messages"."trade_id" IS NOT NULL))));


