INSERT INTO "public"."trades" VALUES ('d9250fab-08fc-47fd-b8a9-5018a03b8597', '3c0c5184-f139-484e-bd08-0bcfdfc914b8', 'NASDAQ', 'short', 1.0000, '2026-01-06 00:00:00+00', '2026-01-05 22:06:00+00', 25.64800000, 25.67500000, -46.76, 27.0000, 46.76, 0.00, 3, NULL, 'נכנסתי לעסקה כי הייתי בטוח שיש smt 4h עם הדאו ויש smt 1h עם הסנופי שקרה כבר בלונדון ולכן חשבתי שבam פשוט ניתן המשכיות ללונדון אז חיפשתי smt fill להמשכיות בגרף 15m מצאתי אחד ונכנסתי על האושר בלוק הראשון שנוצר אחרי הפתיחה שכל זה קרה בפרימיום ככה שהייתי בטוח שזאת אחלה עסקה כי זה הסטאפ שתי שבירות אחת בטווחים הגדולים לכיוון ואחת יותר קטנה לכניסה ואישור כניסה על ob הראשון שנוצר ולכן העסקה הייתה נכונה לכאורה אבל, הייתה לי בעיה בניתוח שלא שמתי לב לזה שבדרך שעה כבר הגענו לתיקון עמוק במיוחד בסנופי ונכנסתי לגאפ 1h ויצרנו PSP 1h שככה אחרי שקיבלנו תגובה מה smt 1h שנוצר בבוקר והגענו לדיסקאונת והגענו לגאפ באותו תווך זמן ויצרנו PSP 1h שהוא באותו כח של smt 1h לכן הוא מסתכל אותו כי הגענו לנזילות פנימית ויצרנו שבירה באותו הכוח ואז בגרף 5m שהוא המקושר ל1h יצרנו psp שהוא האישור לזה שנראה באמת לקבל שינו כיוון ומשם רק נשאר לעלות באמת לגבוה של אתמול שלא נלקח (כי הsmt של הבוקר היה בין מחירי סגירה) ולכן כל העסקה והניתוח שלה לא היה נכון כי הוא כבר בוטל בסשן am כי קיבלנו שבירה באותה רמה . 
