INSERT INTO "public"."trades" VALUES ('3dd4036f-102a-42e4-93d6-9e8e9d53f5a4', 'd9f99ec9-0682-418c-97a5-1d79ae60b1f7', 'MNQ', 'long', 5.0000, '2026-01-05 12:00:00+00', NULL, 100.00000000, 100.00000000, -166.00, -15.5000, 166.00, 0.00, 5, 'Continuation', 'הייתי בריש ביאס אבל לאחר הבנה ושהגרף פשוט טס למעלה יצר המון גאפים וגאפ ב15 דקתי לעליות, חיכיתי לכניסה אליו ומשם יצר אסאמטי ב15 דקתי בניהם והיה סטייה, חיכיתי לאינברס הכי גדול ברגל שהיה ב2 דקתי, נכנסתי, סטופ היה בגוף של הנר מכוון שהיה גאפ שאם לא מכבד אותו אני כבר יהיה בחוץ, ברייק איבן היה מקורי ב5 דקתי אבל היה קרוב מאוד מכוון שה2 דקתי סגר ממש מעל אז החלפתי ספוט לסווינג הבאה וגם היה גאפים לטובתי והאמנתי בעסקה אז רציתי לתת לה לרוץ יותר, טייק פרופיט בגבוה 15 שהתחיל את הרגל והDOL שלי היה ברור לגבי גבוה 5 דקתי/גאפ 15 טרי שלא היינו בו אחרי שהייתי בריש ביאס לכיוון Asia Low.
