INSERT INTO "public"."trades" VALUES ('35f716ac-6f73-4d32-8f8a-0b2b87d394ea', '9ce9091d-58e1-49f5-b46a-a4754186f84d', 'NQ', 'short', 1.0000, '2026-02-19 12:00:00+00', NULL, 0.00000000, NULL, -1100.00, NULL, NULL, 0.00, NULL, NULL, 'נכנסתי יותר מדי עסקאות היום , משהו כמו 5 עסקאות הייתי ממש משוכנע שמשהו הולך לקרות דמיינתי למשהו שאמור לקרות לקחתי עסקה מלפני הפתיחת שוק , לקחתי שוב פעם כמה עסקאות כמה פעמים , העניין הוא שיצרתי המון צפיה למשהו גם ליכולת לעבור היום את המבחן , ובנוסף הבאייס שלי היה לקחת שורט מכיוון שהמחיר ביומי עלה ונגע בגאפ היומי ונסגר מתחתיו אז חיפשתי לרדת למטה , אבל העניין הוא ש4 שעתי המחיר נסגר כנר 2 אז הראה כמו נר ריברסל והשאיר מעליו גאפ גדול 4 שעתי זה היה אמור להיות הנורה האדומה שלי לא הגיוני שנראה ריברסל שככה הנר ה4 שעתי נסגר ולאחר אז שם לקחתי עסקאות לא טובות ולאחר מכן המחיר עלה והייתי משוכנע שאנחנו עכשיו הולכים לרדת אבל זה באמת עוד לא קרה המחיר לא נתן את זה ואמרתי לעצמי פאק איט שזה לא היה דבר כל כך חכם ברגעים שכאלה אני צריך להבין שככה אני הולך לפעול ולהוריד סיכון באותו רגע כי אני מבין שזה לא הולך לקרות  
