INSERT INTO "public"."trades" VALUES ('6f4625ab-a66e-415c-8cb7-7071e5a2e8d1', '5cb072e1-cf49-44fc-8f38-faf9ed5b6531', 'MICRO GOLD', 'long', 1.0000, '2026-02-23 12:00:00+00', '2026-02-23 10:40:00+00', 5168.10000000, 5180.00000000, 126.00, 166.0000, 50.00, 0.00, 3, 'Market Maker Model', 'נכנסתי לעסקה כי זיהיתי קודם כל בגרף היומי נזילות קטלנית למעלה ואז נכנסתי לגרפים היותר קטנים בשביל להבין לאן התנועה זורמת ונכנסתי לגרף של ה15 וזיהיתי שאנחנו בדיוק באמצע ליצור רת הM ונשאר ליצור רגל שניה אז הלכתי לגרף הדקתי לראות אם אכן אפשר להצדיק תנועה קטנה ללמעלה וראיתי שיש הרבה נזילות והבנתי שכנירא זה מה שהם ירצו לעשות אז חיכיתי לאישור של  לצוצ ובוס ואכן קרה וחיכיתי לריטסט יותר עמוק מהקו של השבירה כי ראיתי נזילות קצת יותר בפנים וכשהוא הגיע נכנסתי ושמתי לו את הסטופ מתחת לכל המגמה שאם הוא שובר אותה לא צדקתי בתנועה ואנחנו כנראה בדרך למטה...
